mapper.update:
UPDATE music_reviews
SET
    preference_score = #{preferenceScore},
    running_fit_score = #{runningFitScore},
    review_content = #{reviewContent}
WHERE id = #{id}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM music_reviews
    WHERE member_id = #{memberId}
      AND music_id = #{musicId}
)
